CREATE TABLE `remitentes` (`id_remitente` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_remitente`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `clases_servicio` (`id_clase_servicio` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_clase_servicio`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `modalidades_envio` (`id_modalidad_envio` INT NOT NULL AUTO_INCREMENT, `id_clase_servicio` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `tarifa_base` DECIMAL(11,2) NOT NULL, `capacidad` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_modalidad_envio`), KEY `idx_recurso_categoria` (`id_clase_servicio`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_clase_servicio`) REFERENCES `clases_servicio` (`id_clase_servicio`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `centros_logisticos` (`id_centro_logistico` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_centro_logistico`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `coordinadores` (`id_coordinador` INT NOT NULL AUTO_INCREMENT, `id_centro_logistico` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_coordinador`), KEY `idx_empleado_sede` (`id_centro_logistico`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_centro_logistico`) REFERENCES `centros_logisticos` (`id_centro_logistico`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `envios` (`id_envio` INT NOT NULL AUTO_INCREMENT, `id_remitente` INT NOT NULL, `id_coordinador` INT NOT NULL, `id_centro_logistico` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_envio`), KEY `idx_operacion_persona` (`id_remitente`), KEY `idx_operacion_empleado` (`id_coordinador`), KEY `idx_operacion_sede` (`id_centro_logistico`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_remitente`) REFERENCES `remitentes` (`id_remitente`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_coordinador`) REFERENCES `coordinadores` (`id_coordinador`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_centro_logistico`) REFERENCES `centros_logisticos` (`id_centro_logistico`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `servicios_contratados` (`id_servicio_contratado` INT NOT NULL AUTO_INCREMENT, `id_envio` INT NOT NULL, `id_modalidad_envio` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_servicio_contratado`), KEY `idx_detalle_operacion` (`id_envio`), KEY `idx_detalle_recurso` (`id_modalidad_envio`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_envio`) REFERENCES `envios` (`id_envio`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_modalidad_envio`) REFERENCES `modalidades_envio` (`id_modalidad_envio`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `cobros_envio` (`id_cobro_envio` INT NOT NULL AUTO_INCREMENT, `id_envio` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_cobro_envio`), KEY `idx_pago_operacion` (`id_envio`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_envio`) REFERENCES `envios` (`id_envio`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `rastreo_envio` (`id_rastreo_envio` INT NOT NULL AUTO_INCREMENT, `id_envio` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_rastreo_envio`), KEY `idx_evento_operacion` (`id_envio`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_envio`) REFERENCES `envios` (`id_envio`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
